#!/usr/bin/env bash
# Checks that `kubectl_binary` wires generated files, environment and extra
# arguments through to kubectl, from any working directory.
# --- begin runfiles.bash initialization v3 ---
# Copy-pasted from the Bazel Bash runfiles library v3.
set -uo pipefail; set +e; f=bazel_tools/tools/bash/runfiles/runfiles.bash
# shellcheck disable=SC1090
source "${RUNFILES_DIR:-/dev/null}/$f" 2>/dev/null || \
  source "$(grep -sm1 "^$f " "${RUNFILES_MANIFEST_FILE:-/dev/null}" | cut -f2- -d' ')" 2>/dev/null || \
  source "$0.runfiles/$f" 2>/dev/null || \
  source "$(grep -sm1 "^$f " "$0.runfiles_manifest" | cut -f2- -d' ')" 2>/dev/null || \
  source "$(grep -sm1 "^$f " "$0.exe.runfiles_manifest" | cut -f2- -d' ')" 2>/dev/null || \
  { echo>&2 "ERROR: cannot find $f"; exit 1; }; f=; set -e
# --- end runfiles.bash initialization v3 ---

set -euo pipefail

configmap_dry_run="$(rlocation "${CONFIGMAP_DRY_RUN}")"
config_view="$(rlocation "${CONFIG_VIEW}")"

# Keep the test independent of any kubeconfig on the host.
export HOME="${TEST_TMPDIR}/home"
export KUBECONFIG=
mkdir -p "${HOME}"

elsewhere="${TEST_TMPDIR}/elsewhere"
mkdir -p "${elsewhere}"

echo "--- a generated file referenced with \$(rlocationpath) is found from another directory"
output="$(cd "${elsewhere}" && BUILD_WORKING_DIRECTORY="${elsewhere}" "${configmap_dry_run}")"
grep -q "name: binary-test" <<<"${output}"
grep -q "generated by bazel" <<<"${output}"

echo "--- arguments on the command line are appended"
output="$(cd "${elsewhere}" && "${configmap_dry_run}" --namespace=appended)"
grep -q "namespace: appended" <<<"${output}"

echo "--- env is set for kubectl"
output="$(cd "${elsewhere}" && "${config_view}")"
if [[ "${output}" != "https://binary-test.invalid:6443" ]]; then
  echo "Expected the server from the generated kubeconfig, got: ${output}" >&2
  exit 1
fi
